import { Node, Vec3, Color } from 'cc';
import { createPrimitiveNode, Palette } from './PrimitiveFactory';

export interface CharacterColors {
    skin?: Color;
    shirt?: Color;
    pants?: Color;
    hair?: Color;
    accent?: Color;
}

// Build a simple humanoid from primitive boxes/spheres. Root pivot at feet.
// Returns the root node plus references to body parts for animation.
export interface CharacterParts {
    root: Node;
    body: Node;
    head: Node;
    leftArm: Node;
    rightArm: Node;
    leftLeg: Node;
    rightLeg: Node;
    weaponSlot: Node;
}

export function buildHumanoid(name: string, colors: CharacterColors = {}, scale = 1): CharacterParts {
    const skin   = colors.skin   ?? Palette.skin;
    const shirt  = colors.shirt  ?? Palette.cloth;
    const pants  = colors.pants  ?? Palette.leather;
    const hair   = colors.hair   ?? Palette.hair;

    const root = new Node(name);

    // Legs: vertical center near 0.5
    const leftLeg = createPrimitiveNode('LeftLeg', 'box', new Vec3(0.25, 0.9, 0.25).multiplyScalar(scale), pants);
    leftLeg.setPosition(-0.18 * scale, 0.45 * scale, 0);
    root.addChild(leftLeg);

    const rightLeg = createPrimitiveNode('RightLeg', 'box', new Vec3(0.25, 0.9, 0.25).multiplyScalar(scale), pants);
    rightLeg.setPosition(0.18 * scale, 0.45 * scale, 0);
    root.addChild(rightLeg);

    // Torso
    const body = createPrimitiveNode('Body', 'box', new Vec3(0.7, 0.9, 0.4).multiplyScalar(scale), shirt);
    body.setPosition(0, 1.35 * scale, 0);
    root.addChild(body);

    // Arms
    const leftArm = createPrimitiveNode('LeftArm', 'box', new Vec3(0.22, 0.8, 0.22).multiplyScalar(scale), shirt);
    leftArm.setPosition(-0.46 * scale, 1.35 * scale, 0);
    root.addChild(leftArm);

    const rightArm = createPrimitiveNode('RightArm', 'box', new Vec3(0.22, 0.8, 0.22).multiplyScalar(scale), shirt);
    rightArm.setPosition(0.46 * scale, 1.35 * scale, 0);
    root.addChild(rightArm);

    // Head
    const head = createPrimitiveNode('Head', 'sphere', new Vec3(0.55, 0.55, 0.55).multiplyScalar(scale), skin);
    head.setPosition(0, 2.05 * scale, 0);
    root.addChild(head);

    // Hair cap on top of head
    const hairCap = createPrimitiveNode('Hair', 'sphere', new Vec3(0.58, 0.45, 0.58).multiplyScalar(scale), hair);
    hairCap.setPosition(0, 2.18 * scale, -0.02 * scale);
    root.addChild(hairCap);

    // Weapon slot: empty node attached on right hand
    const weaponSlot = new Node('WeaponSlot');
    weaponSlot.setPosition(0, -0.5 * scale, 0.1 * scale);
    rightArm.addChild(weaponSlot);

    return { root, body, head, leftArm, rightArm, leftLeg, rightLeg, weaponSlot };
}